 chat=["P: Pablo me ha enseñado la carpeta que vio en la mesa de Lucía. ¿Tú la has visto? | O Pablo me mostrou a pasta que viu na mesa da Lucía. Você a viu?",
  "Y: No, solo me contó que había cifras. ¿Qué decían? | Não, só me contou que havia números. O que diziam?",
  "P: Que el coste de impresión viene subiendo desde hace dos años, sobre todo el del papel. | Que o custo de impressão vem subindo há dois anos, sobretudo o do papel.",
  "Y: Es verdad, y los comercios del barrio vienen anunciándose cada vez menos. | É verdade, e os comércios do bairro vêm anunciando cada vez menos.",
  "P: Exacto. Las ventas en papel vienen cayendo desde que abrimos la web. | Exato. As vendas em papel vêm caindo desde que abrimos o site.",
  "Y: Entonces Javier lleva tiempo preocupado. ¿Por qué no nos dice nada? | Então o Javier está preocupado faz tempo. Por que não nos diz nada?",
  "P: Javier viene diciendo desde hace años que el periódico es «la conciencia del barrio». Un hombre así no admite fácilmente los problemas. | O Javier vem dizendo há anos que o jornal é «a consciência do bairro». Um homem assim não admite facilmente os problemas.",
  "Y: Pero eso no justifica que Lucía firme mi trabajo. | Mas isso não justifica que a Lucía assine meu trabalho.",
  "P: Claro que no. Aunque quizá las dos cosas estén relacionadas. Mira esta gráfica: la curva viene bajando sin parar. | Claro que não. Embora talvez as duas coisas estejam relacionadas. Olhe este gráfico: a curva vem descendo sem parar.",
  "Y: Necesito datos reales. ¿Quién puede enseñarme las facturas? | Preciso de dados reais. Quem pode me mostrar as faturas?",
  "P: La imprenta. Mañana voy a ver a Memo; si quieres venir, no se lo cuentes a nadie de la redacción. | A gráfica. Amanhã vou ver o Memo; se quiser vir, não conte a ninguém da redação."],
 tap=[("¿Desde cuándo sube el coste de impresión?","Desde quando sobe o custo de impressão?",["Desde hace dos años","Desde ayer","Desde hace una década"],0,2,"P: “viene subiendo desde hace dos años”"),
  ("¿Qué viene diciendo Javier desde hace años?","O que o Javier vem dizendo há anos?",["Que quiere jubilarse","Que el periódico es la conciencia del barrio","Que Lucía es su hija"],1,6,"P: “Javier viene diciendo desde hace años que el periódico es «la conciencia del barrio»”"),
  ("¿A quién irá a ver Santiago mañana?","A quem o Santiago vai ver amanhã?",["Al banco","A Lucía","A Memo, de la imprenta"],2,10,"P: “Mañana voy a ver a Memo”")],
 swap=("Tendência até hoje: «venir + gerundio». «Viene subiendo desde hace años». 🎓 DELE B2: describir tendencias y procesos.",
  [("Viene + gerundio…",[("Viene","Vem"),("Vienen","Vêm"),("Vengo","Venho")],[("subiendo","subindo"),("creciendo","crescendo"),("cayendo","caindo")],"."),
   ("Desde hace…",[("El precio viene subiendo","O preço vem subindo"),("La venta viene bajando","A venda vem caindo"),("El interés viene creciendo","O interesse vem crescendo")],[("desde hace dos años","há dois anos"),("desde hace meses","há meses"),("desde hace una década","há uma década")],".")]),
 chat2=["Y: ¿Qué tendencia ves en el barrio últimamente? | Que tendência você vê no bairro ultimamente?",
  "P: El alquiler viene subiendo y los vecinos vienen mudándose a las afueras. | O aluguel vem subindo e os vizinhos vêm se mudando para a periferia.",
  "Y: ¿Y las tiendas de siempre? | E as lojas de sempre?",
  "P: Vienen cerrando una detrás de otra, por desgracia. | Vêm fechando uma atrás da outra, infelizmente.",
  "Y: Habría que escribir un reportaje sobre eso. | Teríamos que escrever uma reportagem sobre isso.",
  "P: De acuerdo, pero con tu firma esta vez. | De acordo, mas com a sua assinatura desta vez."],
 slang=("Santiago",["📈","#AE3EC9"],["F: Parce, esa vaina de las cuentas del periódico está muy complicada. | Cara, essa coisa das contas do jornal está bem complicada.","Y: ¿En serio? Yo pensaba que íbamos bien. | Sério? Eu achava que íamos bem.","F: Qué va, hermano, la cosa viene mal desde hace rato. | Que nada, irmão, a coisa vai mal faz tempo.","Y: Ese es el problema: nadie dice nada y todo se vuelve un enredo. | Esse é o problema: ninguém diz nada e tudo vira um enrosco.","F: Tranquilo, de pronto Javier saca un as de la manga. | Calma, quem sabe o Javier tira um coringa da manga.","Y: Ojalá, porque esto está de película. | Tomara, porque isso está de filme."],
  {"parce":"cara, parceiro (Colômbia)","vaina":"coisa, negócio (Colômbia)","qué va":"que nada","enredo":"enrosco, confusão","de pronto":"quem sabe, talvez (Colômbia)"},["parce","de pronto"]),
