 chat=["P: Pásale, pásale. Santiago me dijo que querías preguntarme por la imprenta. | Entre, entre. O Santiago me disse que você queria me perguntar pela gráfica.",
  "Y: Sí, quería saber cómo están las cuentas del periódico con ustedes. | Sim, queria saber como estão as contas do jornal com vocês.",
  "P: Pues mira, ahorita todo va mejorando poco a poco. Javier me va pagando las facturas atrasadas en plazos. | Pois olhe, agora tudo vai melhorando pouco a pouco. O Javier vai me pagando as faturas atrasadas em parcelas.",
  "Y: ¿Atrasadas? ¿Cuánto debe el periódico? | Atrasadas? Quanto o jornal deve?",
  "P: No me corresponde decirte la cifra, pero la deuda va bajando mes a mes. Yo confío en Javier. | Não me cabe dizer o valor, mas a dívida vai diminuindo mês a mês. Eu confio no Javier.",
  "Y: ¿Y por qué ahora firma Lucía los reportajes más importantes? | E por que agora a Lucía assina as reportagens mais importantes?",
  "P: Eso sí que no lo sé. Ayer vino a pedirme copias de las facturas y se fue con cara de preocupación. | Isso eu realmente não sei. Ontem ela veio me pedir cópias das faturas e foi embora com cara de preocupação.",
  "Y: ¿Preocupación? Yo pensaba que solo le importaba su carrera. | Preocupação? Eu achava que só se importava com a carreira.",
  "P: Las personas van cambiando, ¿sabes? Hasta la más ambiciosa va aprendiendo a pedir ayuda. | As pessoas vão mudando, sabe? Até a mais ambiciosa vai aprendendo a pedir ajuda.",
  "Y: Tienes razón. Quizá me he ido haciendo una idea equivocada de ella. | Você tem razão. Talvez eu tenha ido formando uma ideia errada dela.",
  "P: Puede ser. Por cierto, Lucía llevaba un papel de un banco. Pregúntale por qué, pero con tacto, ¿eh? | Pode ser. Aliás, a Lucía levava um papel de um banco. Pergunte a ela por quê, mas com tato, hein?"],
 tap=[("¿Cómo van las cuentas con la imprenta?","Como vão as contas com a gráfica?",["Van mejorando poco a poco","Están perdidas","Están saldadas"],0,2,"P: “todo va mejorando poco a poco”"),
  ("¿Qué pidió Lucía ayer a Memo?","O que a Lucía pediu ontem ao Memo?",["Dinero","Copias de las facturas","Un trabajo"],1,6,"P: “vino a pedirme copias de las facturas”"),
  ("¿De dónde era el papel de Lucía?","De onde era o papel da Lucía?",["De un hospital","De la alcaldía","De un banco"],2,10,"P: “Lucía llevaba un papel de un banco”")],
 swap=("Processo gradual: «ir + gerundio». «Va mejorando poco a poco». 🎓 DELE B2: describir cambios y evolución.",
  [("Va + gerundio…",[("Va","Vai"),("Van","Vão"),("Voy","Vou")],[("mejorando","melhorando"),("pagando","pagando"),("aprendiendo","aprendendo")],"."),
   ("Poco a poco…",[("Poco a poco me voy","Pouco a pouco vou me"),("Poco a poco se va","Pouco a pouco ele vai se"),("Poco a poco nos vamos","Pouco a pouco vamos nos")],[("haciendo una idea","formando uma ideia"),("dando cuenta","dando conta"),("acostumbrando","acostumando")],".")]),
 chat2=["Y: ¿Cómo va tu hermano después de la operación? | Como vai seu irmão depois da operação?",
  "P: Va recuperándose poco a poco, aunque se cansa pronto. | Vai se recuperando pouco a pouco, embora se canse rápido.",
  "Y: ¿Y la imprenta? ¿Va entrando más trabajo? | E a gráfica? Vai entrando mais trabalho?",
  "P: Sí, van llegando encargos nuevos, pero hay que ir despacio. | Sim, vão chegando encomendas novas, mas é preciso ir devagar.",
  "Y: Me alegro muchísimo. | Fico muito feliz.",
  "P: Gracias, vecino. Todo se va arreglando. | Obrigado, vizinho. Tudo vai se ajeitando."],
 slang=("Memo",["🖨️","#AE3EC9"],["F: Órale, wey, qué gusto verte por aquí. | Beleza, cara, que prazer te ver por aqui.","Y: Igualmente. Oye, ¿cómo va el jale en la imprenta? | Igualmente. Ei, como vai o trampo na gráfica?","F: Ahí la llevamos, no te quejes, hay chamba. | Vamos levando, não reclame, tem trabalho.","Y: ¿Y la deuda del periódico? ¿Es mucha lana? | E a dívida do jornal? É muita grana?","F: Eso no te lo digo ni de chiste, es cosa de Javier. | Isso eu não te digo nem por brincadeira, é coisa do Javier.","Y: Ándale, qué reservado eres, pero te entiendo. | Pois é, como você é reservado, mas te entendo."],
  {"órale":"beleza, nossa (México)","wey":"cara, mano (México)","jale":"trampo, trabalho (México)","lana":"grana, dinheiro (México)","ni de chiste":"nem por brincadeira, de jeito nenhum (México)"},["jale","lana"]),
 real=("Ahora todo va mejorando","Ahorita to' va mejorando","na fala, «ahora» vira «ahorita» (México) e «todo» perde o «d» final: «to'»"),
